INSERT INTO `artifact` (`artifactID`, `name`, `set_name`, `max_rarity`, `stock`, `image_url`, `price`, `piece_bonus_2`, `piece_bonus_4`) VALUES
('03194207-a263-43d1-8085-c95974271ea1', 'circlet-of-logos', 'Unfinished Reverie', '5', 1000, 'https://genshin.jmp.blue/artifacts/unfinished-reverie/circlet-of-logos', 1000.0000, 'ATK +18%', 'After leaving combat for 3s, DMG dealt increased by 50%. In combat, if no Burning opponents are nearby for more than 6s, this DMG Bonus will decrease by 10% per second until it reaches 0%. When a Burning opponent exists, it will increase by 10% instead until it reaches 50%. This effect still triggers if the equipping character is off-field.'),
('05472bb4-9b8b-4b09-ba1f-40c347bf25b8', 'sands-of-eon', 'Emblem Of Severed Fate', '5', 1000, 'https://genshin.jmp.blue/artifacts/emblem-of-severed-fate/sands-of-eon', 1000.0000, 'Energy Recharge + 20%', 'Increases Elemental Burst DMG by 25% of Energy Recharge. A maximum of 75% bonus DMG can be obtained in this way.'),
('069378ee-1bb6-4f31-a81b-4118211bd15c', 'flower-of-life', 'Gladiator\'s Finale', '5', 1000, 'https://genshin.jmp.blue/artifacts/gladiator-s-finale/flower-of-life', 1000.0000, 'ATK +18%', 'If the wielder of this artifact set uses a Sword, Claymore or Polearm, increases their Normal Attack DMG by 35%.'),
('09532a62-b678-469d-a1d4-29e94c95fc55', 'circlet-of-logos', 'Berserker', '4', 1000, 'https://genshin.jmp.blue/artifacts/berserker/circlet-of-logos', 1000.0000, 'CRIT Rate +12%', 'When HP is below 70%, CRIT Rate increases by an additional 24%.'),
('0de18a05-97e6-49fe-a97c-ae62a4e43f95', 'flower-of-life', 'Lavawalker', '5', 1000, 'https://genshin.jmp.blue/artifacts/lavawalker/flower-of-life', 1000.0000, 'Pyro RES increased by 40%', 'Increases DMG against enemies that are Burning or affected by Pyro by 35%.'),
('0f78986c-a064-4766-bf7d-53f8025e093d', 'sands-of-eon', 'Lavawalker', '5', 1000, 'https://genshin.jmp.blue/artifacts/lavawalker/sands-of-eon', 1000.0000, 'Pyro RES increased by 40%', 'Increases DMG against enemies that are Burning or affected by Pyro by 35%.'),
('1053c374-c4fe-4609-9e34-ec3ae78e3697', 'flower-of-life', 'Tiny Miracle', '4', 1000, 'https://genshin.jmp.blue/artifacts/tiny-miracle/flower-of-life', 1000.0000, 'All Elemental RES increased by 20%', 'Incoming elemental DMG increases corresponding Elemental RES by 30% for 10s. Can only occur once every 10s.'),
('10a11e0b-dfe7-406b-bbcf-83b02b1db06e', 'sands-of-eon', 'Nymph\'s Dream', '5', 1000, 'https://genshin.jmp.blue/artifacts/nymph-s-dream/sands-of-eon', 1000.0000, 'Hydro DMG Bonus +15%', 'After Normal, Charged, and Plunging Attacks, Elemental Skills, and Elemental Bursts hit opponents, 1 stack of Mirrored Nymph will be triggered, lasting 8s. When under the effect of 1, 2, or 3, or more Mirrored Nymph stacks, ATK will be increased by 7%/16%/25%, and Hydro DMG will be increased by 4%/9%/15%. Mirrored Nymph stacks created by Normal, Charged, and Plunging Attacks, Elemental Skills, and Elemental Bursts exist independently.'),
('10b2ce58-d8b8-4e83-aba7-346e076e1acf', 'goblet-of-eonothem', 'Shimenawa\'s Reminiscence', '5', 1000, 'https://genshin.jmp.blue/artifacts/shimenawa-s-reminiscence/goblet-of-eonothem', 1000.0000, 'ATK +18%', 'When casting an Elemental Skill, if the character has 15 or more Energy, they lose 15 Energy and Normal/Charged/ Plunging Attack DMG is increased by 50% for 10s. This effect will not trigger again during that duration.'),
('12934262-a6ac-4f0e-b1bf-4d6a41ca1698', 'goblet-of-eonothem', 'Archaic Petra', '5', 1000, 'https://genshin.jmp.blue/artifacts/archaic-petra/goblet-of-eonothem', 1000.0000, 'Gain a 15% Geo DMG Bonus.', 'Upon obtaining an Elemental Shard created through a Crystallize Reaction, all party members gain a 35% DMG Bonus for that particular element for 10s. Only one form of Elemental DMG Bonus can be gained in this manner at any one time.'),
('12d471d3-9f6b-4efd-b221-edf0c289c8d2', 'plume-of-death', 'Heart of Depth', '5', 1000, 'https://genshin.jmp.blue/artifacts/heart-of-depth/plume-of-death', 1000.0000, 'Hydro DMG Bonus +15%', 'After using Elemental Skill, increases Normal Attack and Charged Attack DMG by 30% for 15s.'),
('131657be-314f-4499-aa75-cbfa77df5d2f', 'sands-of-eon', 'Gilded Dreams', '5', 1000, 'https://genshin.jmp.blue/artifacts/gilded-dreams/sands-of-eon', 1000.0000, 'Elemental Mastery +80', 'Within 8s of triggering an Elemental Reaction, the character equipping this will obtain buffs based on the Elemental Type of the other party members, ATK is increased by 14% for each party member whose Elemental Type is the same as the equipping character, and Elemental Mastery is increased by 50 for every party member with a different Elemental Type. Each of the aforementioned buffs will count up to 3 characters. This effect can be triggered once every 8s. The character who equips this can still trigger its effects when not on the field.'),
('131d9573-d61f-40be-9f0e-a1607f2eddb5', 'plume-of-death', 'Nymph\'s Dream', '5', 1000, 'https://genshin.jmp.blue/artifacts/nymph-s-dream/plume-of-death', 1000.0000, 'Hydro DMG Bonus +15%', 'After Normal, Charged, and Plunging Attacks, Elemental Skills, and Elemental Bursts hit opponents, 1 stack of Mirrored Nymph will be triggered, lasting 8s. When under the effect of 1, 2, or 3, or more Mirrored Nymph stacks, ATK will be increased by 7%/16%/25%, and Hydro DMG will be increased by 4%/9%/15%. Mirrored Nymph stacks created by Normal, Charged, and Plunging Attacks, Elemental Skills, and Elemental Bursts exist independently.'),
('1363fd73-720f-46de-8962-a36e4024325d', 'goblet-of-eonothem', 'Vermillion Hereafter', '5', 1000, 'https://genshin.jmp.blue/artifacts/vermillion-hereafter/goblet-of-eonothem', 1000.0000, 'ATK +18%', 'After using an Elemental Burst. this character will gain the Nascent Light effect, increasing their ATK by 8% for 16s. When the character\'s HP decreases, their ATK will further increase by 10%. This increase can occur this way maximum of 4 times. This effect can be triggered once every 0.8s. Nascent Light will be dispelled when the character leaves the field. If an Elemental Burst is used again during the duration of Nascent Light, the original Nascent Light will be dispelled.'),
('139aa42b-39fa-49e6-b82a-f4d50fb0b9e9', 'circlet-of-logos', 'Archaic Petra', '5', 1000, 'https://genshin.jmp.blue/artifacts/archaic-petra/circlet-of-logos', 1000.0000, 'Gain a 15% Geo DMG Bonus.', 'Upon obtaining an Elemental Shard created through a Crystallize Reaction, all party members gain a 35% DMG Bonus for that particular element for 10s. Only one form of Elemental DMG Bonus can be gained in this manner at any one time.'),
('13de0815-27c6-4e0a-8f98-ccb24155a74f', 'sands-of-eon', 'Lucky Dog', '3', 1000, 'https://genshin.jmp.blue/artifacts/lucky-dog/sands-of-eon', 1000.0000, 'DEF increased by 100.', 'Picking up Mora restores 300 HP.'),
('15c7b83a-016f-499c-8a89-0088614bdd9b', 'circlet-of-logos', 'Tenacity of the Millelith', '5', 1000, 'https://genshin.jmp.blue/artifacts/tenacity-of-the-millelith/circlet-of-logos', 1000.0000, 'HP +20%', 'When an Elemental Skill hits an opponent, the ATK of all nearby party members is increased by 20% and their Shield Strength is increased by 30% for 3s. This effect can be triggered once every 0.5s. This effect can still be triggered even when the character who is using this artifact set is not on the field.'),
('16a65bb3-8c31-4955-956c-e33b4584b38e', 'flower-of-life', 'Lucky Dog', '3', 1000, 'https://genshin.jmp.blue/artifacts/lucky-dog/flower-of-life', 1000.0000, 'DEF increased by 100.', 'Picking up Mora restores 300 HP.'),
('18e28ca7-39d6-491f-a21a-1995bcaa55e4', 'flower-of-life', 'Thundering Fury', '5', 1000, 'https://genshin.jmp.blue/artifacts/thundering-fury/flower-of-life', 1000.0000, 'Gain a 15% Electro DMG Bonus.', 'Increases damage caused by Overloaded, Electro-Charged, and Superconduct DMG by 40%. Triggering such effects decreases Elemental Skill CD by 1s. Can only occur once every 0.8s.'),
('1b57c20d-4bdb-4a50-a188-2ba42cb79832', 'circlet-of-logos', 'Bloodstained Chivalry', '5', 1000, 'https://genshin.jmp.blue/artifacts/bloodstained-chivalry/circlet-of-logos', 1000.0000, 'Physical DMG +25%', 'After defeating an opponent, increases Charged Attack DMG by 50%, and reduces its Stamina cost to 0 for 10s.'),
('1c44c167-5443-4a0f-aaa6-44333b7509dd', 'circlet-of-logos', 'Viridescent Venerer', '5', 1000, 'https://genshin.jmp.blue/artifacts/viridescent-venerer/circlet-of-logos', 1000.0000, 'Gain a 15% Anemo DMG Bonus.', 'Increases Swirl DMG by 60%. Decreases opponent\'s Elemental RES to the element infused in the Swirl by 40% for 10s.'),
('1c5815d8-220f-4349-a57b-21ebb50ac9cb', 'plume-of-death', 'Gilded Dreams', '5', 1000, 'https://genshin.jmp.blue/artifacts/gilded-dreams/plume-of-death', 1000.0000, 'Elemental Mastery +80', 'Within 8s of triggering an Elemental Reaction, the character equipping this will obtain buffs based on the Elemental Type of the other party members, ATK is increased by 14% for each party member whose Elemental Type is the same as the equipping character, and Elemental Mastery is increased by 50 for every party member with a different Elemental Type. Each of the aforementioned buffs will count up to 3 characters. This effect can be triggered once every 8s. The character who equips this can still trigger its effects when not on the field.'),
('1cdd8100-2612-43fe-8cbb-df7c094ed006', 'plume-of-death', 'Vermillion Hereafter', '5', 1000, 'https://genshin.jmp.blue/artifacts/vermillion-hereafter/plume-of-death', 1000.0000, 'ATK +18%', 'After using an Elemental Burst. this character will gain the Nascent Light effect, increasing their ATK by 8% for 16s. When the character\'s HP decreases, their ATK will further increase by 10%. This increase can occur this way maximum of 4 times. This effect can be triggered once every 0.8s. Nascent Light will be dispelled when the character leaves the field. If an Elemental Burst is used again during the duration of Nascent Light, the original Nascent Light will be dispelled.'),
('1cfbcc61-e611-4db4-a080-cf46d650e225', 'circlet-of-logos', 'Instructor', '4', 1000, 'https://genshin.jmp.blue/artifacts/instructor/circlet-of-logos', 1000.0000, 'Increases Elemental Mastery by 80.', 'After using Elemental Skill, increases all party members\' Elemental Mastery by 120 for 8s.'),
('20e7c746-95dc-46ab-ab51-3ca40a180a3f', 'plume-of-death', 'Husk of Opulent Dreams', '5', 1000, 'https://genshin.jmp.blue/artifacts/husk-of-opulent-dreams/plume-of-death', 1000.0000, 'DEF +30%', 'A character equipped with this Artifact set will obtain the Curiosity effect in the following conditions: When on the field, the character gains 1 stack after hitting an opponent with a Geo attack, triggering a maximum of once every 0.3s. When off the field, the character gains 1 stack every 3s. Curiosity can stack up to 4 times, each providing 6% DEF and a 6% Geo DMG Bonus. When 6 seconds pass without gaining a Curiosity stack, 1 stack is lost.'),
('20fa2362-63b5-485c-86f9-224bddb06634', 'sands-of-eon', 'Tenacity of the Millelith', '5', 1000, 'https://genshin.jmp.blue/artifacts/tenacity-of-the-millelith/sands-of-eon', 1000.0000, 'HP +20%', 'When an Elemental Skill hits an opponent, the ATK of all nearby party members is increased by 20% and their Shield Strength is increased by 30% for 3s. This effect can be triggered once every 0.5s. This effect can still be triggered even when the character who is using this artifact set is not on the field.'),
('23138ffe-2172-4295-9e7b-5507bbbc5b33', 'flower-of-life', 'Marechaussee Hunter', '5', 1000, 'https://genshin.jmp.blue/artifacts/marechaussee-hunter/flower-of-life', 1000.0000, 'Normal and Charged Attack DMG +15%.', 'When current HP increases or decreases, CRIT Rate will be increased by 12% for 5s. Max 3 stacks.'),
('232d37d0-49cd-41f2-9c37-93b6e53c0d91', 'plume-of-death', 'Thundering Fury', '5', 1000, 'https://genshin.jmp.blue/artifacts/thundering-fury/plume-of-death', 1000.0000, 'Gain a 15% Electro DMG Bonus.', 'Increases damage caused by Overloaded, Electro-Charged, and Superconduct DMG by 40%. Triggering such effects decreases Elemental Skill CD by 1s. Can only occur once every 0.8s.'),
('24f0853b-1563-4668-a9da-b81b5a5619e3', 'sands-of-eon', 'Shimenawa\'s Reminiscence', '5', 1000, 'https://genshin.jmp.blue/artifacts/shimenawa-s-reminiscence/sands-of-eon', 1000.0000, 'ATK +18%', 'When casting an Elemental Skill, if the character has 15 or more Energy, they lose 15 Energy and Normal/Charged/ Plunging Attack DMG is increased by 50% for 10s. This effect will not trigger again during that duration.'),
('25d1d366-762a-47e5-a010-42893a5abc4c', 'plume-of-death', 'Scholar', '4', 1000, 'https://genshin.jmp.blue/artifacts/scholar/plume-of-death', 1000.0000, 'Energy Recharge +20%.', 'Gaining Energy gives 3 Energy to all party members who have a bow or a catalyst equipped. Can only occurs once every 3s.'),
('25eca05c-fd58-45ec-82b6-d0d1fddb7962', 'plume-of-death', 'Echoes of an Offering', '5', 1000, 'https://genshin.jmp.blue/artifacts/echoes-of-an-offering/plume-of-death', 1000.0000, 'ATK +18%', 'When Normal Attacks hit opponents, there is a 36% chance that it will trigger Valley Rite, which will increase Normal Attack DMG by 70% of ATK. \nThis effect will be dispelled 0.05s after a Normal Attack deals DMG. \nIf a Normal Attack fails to trigger Valley Rite, the odds of it triggering the next time will increase by 20%. \nThis trigger can occur once every 0.2s.'),
('2641863d-c49b-4a4e-88ec-9f1dd70d7b52', 'plume-of-death', 'Gladiator\'s Finale', '5', 1000, 'https://genshin.jmp.blue/artifacts/gladiator-s-finale/plume-of-death', 1000.0000, 'ATK +18%', 'If the wielder of this artifact set uses a Sword, Claymore or Polearm, increases their Normal Attack DMG by 35%.'),
('26a4a09a-eca4-41f5-b020-4e93cba4e6e3', 'sands-of-eon', 'Deepwood Memories', '5', 1000, 'https://genshin.jmp.blue/artifacts/deepwood-memories/sands-of-eon', 1000.0000, 'Dendro DMG Bonus +15%', 'After Elemental Skills or Bursts hit opponents, the targets\' Dendro RES will be decreased by 30% for 8s. This effect can be triggered even if the equipping character is not on the field.'),
('27bc943e-ac36-4486-8bf8-1a8e90e757f3', 'sands-of-eon', 'Gambler', '4', 1000, 'https://genshin.jmp.blue/artifacts/gambler/sands-of-eon', 1000.0000, 'Elemental Skill DMG increased by 20%', 'Defeating an enemy has 100% chance to remove Elemental Skill CD. Can only occur once every 15s.'),
('2897b677-4334-497f-80b4-93db8ddbd30e', 'goblet-of-eonothem', 'Marechaussee Hunter', '5', 1000, 'https://genshin.jmp.blue/artifacts/marechaussee-hunter/goblet-of-eonothem', 1000.0000, 'Normal and Charged Attack DMG +15%.', 'When current HP increases or decreases, CRIT Rate will be increased by 12% for 5s. Max 3 stacks.'),
('29082d0f-75ff-4826-b330-614d0789e797', 'flower-of-life', 'Scholar', '4', 1000, 'https://genshin.jmp.blue/artifacts/scholar/flower-of-life', 1000.0000, 'Energy Recharge +20%.', 'Gaining Energy gives 3 Energy to all party members who have a bow or a catalyst equipped. Can only occurs once every 3s.'),
('2a49472a-29f7-4582-8594-1a743762a6bf', 'circlet-of-logos', 'Lavawalker', '5', 1000, 'https://genshin.jmp.blue/artifacts/lavawalker/circlet-of-logos', 1000.0000, 'Pyro RES increased by 40%', 'Increases DMG against enemies that are Burning or affected by Pyro by 35%.'),
('2aed34a9-5a6f-4f70-af22-8c9f595d0379', 'goblet-of-eonothem', 'Bloodstained Chivalry', '5', 1000, 'https://genshin.jmp.blue/artifacts/bloodstained-chivalry/goblet-of-eonothem', 1000.0000, 'Physical DMG +25%', 'After defeating an opponent, increases Charged Attack DMG by 50%, and reduces its Stamina cost to 0 for 10s.'),
('2bc08fcb-532d-4dcc-ba0a-c1c557ff8929', 'flower-of-life', 'Unfinished Reverie', '5', 1000, 'https://genshin.jmp.blue/artifacts/unfinished-reverie/flower-of-life', 1000.0000, 'ATK +18%', 'After leaving combat for 3s, DMG dealt increased by 50%. In combat, if no Burning opponents are nearby for more than 6s, this DMG Bonus will decrease by 10% per second until it reaches 0%. When a Burning opponent exists, it will increase by 10% instead until it reaches 50%. This effect still triggers if the equipping character is off-field.'),
('2c207163-f800-4961-b2df-5e13b811d0e0', 'goblet-of-eonothem', 'The Exile', '4', 1000, 'https://genshin.jmp.blue/artifacts/the-exile/goblet-of-eonothem', 1000.0000, 'Energy Recharge +20%', 'Using an Elemental Burst regenerates 2 Energy for other party members every 2s for 6s. This effect cannot stack.'),
('2c352b3d-83e6-4c0a-a3bd-69a52ba29922', 'plume-of-death', 'Deepwood Memories', '5', 1000, 'https://genshin.jmp.blue/artifacts/deepwood-memories/plume-of-death', 1000.0000, 'Dendro DMG Bonus +15%', 'After Elemental Skills or Bursts hit opponents, the targets\' Dendro RES will be decreased by 30% for 8s. This effect can be triggered even if the equipping character is not on the field.'),
('2ff21043-9b02-4523-9512-277ecc926e1f', 'plume-of-death', 'Golden Troupe', '5', 1000, 'https://genshin.jmp.blue/artifacts/golden-troupe/plume-of-death', 1000.0000, 'Increases Elemental Skill DMG by 20%.', 'Increases Elemental Skill DMG by 25%. Additionally, when not on the field, Elemental Skill DMG will be further increased by 25%. This effect will be cleared 2s after taking the field.'),
('3002c7b8-5557-4f7d-b924-0d420e41e096', 'circlet-of-logos', 'Flower of Paradise Lost', '5', 1000, 'https://genshin.jmp.blue/artifacts/flower-of-paradise-lost/circlet-of-logos', 1000.0000, 'Increases Elemental Mastery by 80', 'The equipping character\'s Bloom, Hyperbloom, and Burgeon reaction DMG are increased by 40%. Additionally, after the equipping character triggers Bloom, Hyperbloom, or Burgeon, they will gain another 25% bonus to the effect mentioned prior. Each stack of this lasts 10s. Max 4 stacks simultaneously. This effect can only be triggered once per second. The character who equips this can still trigger its effects when not on the field.'),
('30e78e32-0724-48d5-8e35-9db7872a509d', 'flower-of-life', 'Bloodstained Chivalry', '5', 1000, 'https://genshin.jmp.blue/artifacts/bloodstained-chivalry/flower-of-life', 1000.0000, 'Physical DMG +25%', 'After defeating an opponent, increases Charged Attack DMG by 50%, and reduces its Stamina cost to 0 for 10s.'),
('30f16989-193a-40c9-b88b-4136d1a2f9a0', 'circlet-of-logos', 'Martial Artist', '4', 1000, 'https://genshin.jmp.blue/artifacts/martial-artist/circlet-of-logos', 1000.0000, 'Increases Normal Attack and Charged Attack DMG by 15%.', 'After using Elemental Skill, increases Normal Attack and Charged Attack DMG by 25% for 8s.'),
('31ad93a7-5e25-4e24-8b6b-bb7cd5710079', 'plume-of-death', 'Maiden Beloved', '5', 1000, 'https://genshin.jmp.blue/artifacts/maiden-beloved/plume-of-death', 1000.0000, 'Character Healing Effectiveness +15%', 'Using an Elemental Skill or Burst increases healing received by all party members by 20% for 10s.'),
('328ef113-03db-463a-ba5a-2fbb52cecbb2', 'sands-of-eon', 'Echoes of an Offering', '5', 1000, 'https://genshin.jmp.blue/artifacts/echoes-of-an-offering/sands-of-eon', 1000.0000, 'ATK +18%', 'When Normal Attacks hit opponents, there is a 36% chance that it will trigger Valley Rite, which will increase Normal Attack DMG by 70% of ATK. \nThis effect will be dispelled 0.05s after a Normal Attack deals DMG. \nIf a Normal Attack fails to trigger Valley Rite, the odds of it triggering the next time will increase by 20%. \nThis trigger can occur once every 0.2s.'),
('3530521c-93cc-406f-9c55-751c72314059', 'goblet-of-eonothem', 'Resolution of Sojourner', '4', 1000, 'https://genshin.jmp.blue/artifacts/resolution-of-sojourner/goblet-of-eonothem', 1000.0000, 'ATK +18%', 'Increases Charged Attack CRIT Rate by 30%.'),
('35391661-3a8e-45f4-a32c-182354a5af07', 'flower-of-life', 'Adventurer', '3', 1000, 'https://genshin.jmp.blue/artifacts/adventurer/flower-of-life', 1000.0000, 'Max HP increased by 1,000.', 'Opening chest regenerates 30% Max HP over 5s.'),
('3548c6f4-6761-4d6b-ad28-033ab2b85c3c', 'sands-of-eon', 'Marechaussee Hunter', '5', 1000, 'https://genshin.jmp.blue/artifacts/marechaussee-hunter/sands-of-eon', 1000.0000, 'Normal and Charged Attack DMG +15%.', 'When current HP increases or decreases, CRIT Rate will be increased by 12% for 5s. Max 3 stacks.'),
