('60374d24-c673-4def-9b49-9cea45e1e575', 'plume-of-death', 'The Exile', '4', 1000, 'https://genshin.jmp.blue/artifacts/the-exile/plume-of-death', 1000.0000, 'Energy Recharge +20%', 'Using an Elemental Burst regenerates 2 Energy for other party members every 2s for 6s. This effect cannot stack.'),
