('7363e678-fc6a-49ac-b5e7-9fdb47022bd0', 'flower-of-life', 'Crimson Witch of Flames', '5', 1000, 'https://genshin.jmp.blue/artifacts/crimson-witch-of-flames/flower-of-life', 1000.0000, 'Gain a 15% Pyro DMG Bonus.', 'Increases Overloaded and Burning DMG by 40%. Increases Vaporize and Melt DMG by 15%. Using an Elemental Skill increases 2-Piece Set effects by 50% for 10s. Max 3 stacks.'),
('73cbbb63-c072-408d-84df-813fccc4e8c8', 'flower-of-life', 'Vourukasha\'s Glow', '5', 1000, 'https://genshin.jmp.blue/artifacts/vourukasha-s-glow/flower-of-life', 1000.0000, 'HP +20%', 'Elemental Skill and Elemental Burst DMG will be increased by 10%. After the equipping character takes DMG, the aforementioned DMG bonus is increased by 80% for 5s. This effect increase can have 5 stacks. The duration of each stack is counted independently. These effects can be triggered even when the equipping character is not on the field.'),
('751b4ab4-ee72-4f3f-8b78-8bdbb581d204', 'circlet-of-logos', 'Vourukasha\'s Glow', '5', 1000, 'https://genshin.jmp.blue/artifacts/vourukasha-s-glow/circlet-of-logos', 1000.0000, 'HP +20%', 'Elemental Skill and Elemental Burst DMG will be increased by 10%. After the equipping character takes DMG, the aforementioned DMG bonus is increased by 80% for 5s. This effect increase can have 5 stacks. The duration of each stack is counted independently. These effects can be triggered even when the equipping character is not on the field.'),
('7588eed0-a6d4-4c96-bc09-a79b5a76ce7c', 'goblet-of-eonothem', 'Tenacity of the Millelith', '5', 1000, 'https://genshin.jmp.blue/artifacts/tenacity-of-the-millelith/goblet-of-eonothem', 1000.0000, 'HP +20%', 'When an Elemental Skill hits an opponent, the ATK of all nearby party members is increased by 20% and their Shield Strength is increased by 30% for 3s. This effect can be triggered once every 0.5s. This effect can still be triggered even when the character who is using this artifact set is not on the field.'),
('77edfcd1-f719-4fa5-a2b9-758fc4cd3ab3', 'sands-of-eon', 'Martial Artist', '4', 1000, 'https://genshin.jmp.blue/artifacts/martial-artist/sands-of-eon', 1000.0000, 'Increases Normal Attack and Charged Attack DMG by 15%.', 'After using Elemental Skill, increases Normal Attack and Charged Attack DMG by 25% for 8s.'),
('785b0b26-d262-48f0-bdbb-8159a927742d', 'sands-of-eon', 'Brave Heart', '4', 1000, 'https://genshin.jmp.blue/artifacts/brave-heart/sands-of-eon', 1000.0000, 'ATK +18%', 'Increases DMG by 30% against enemies with more than 50% HP.'),
('7916e9d3-b663-4e3c-9678-746b84ef5c74', 'goblet-of-eonothem', 'Gladiator\'s Finale', '5', 1000, 'https://genshin.jmp.blue/artifacts/gladiator-s-finale/goblet-of-eonothem', 1000.0000, 'ATK +18%', 'If the wielder of this artifact set uses a Sword, Claymore or Polearm, increases their Normal Attack DMG by 35%.'),
('7a4ae485-4507-4cf6-83e6-1463169007e3', 'circlet-of-logos', 'Brave Heart', '4', 1000, 'https://genshin.jmp.blue/artifacts/brave-heart/circlet-of-logos', 1000.0000, 'ATK +18%', 'Increases DMG by 30% against enemies with more than 50% HP.'),
('7df94cbd-0926-466b-b429-8af31450f302', 'sands-of-eon', 'Berserker', '4', 1000, 'https://genshin.jmp.blue/artifacts/berserker/sands-of-eon', 1000.0000, 'CRIT Rate +12%', 'When HP is below 70%, CRIT Rate increases by an additional 24%.'),
('7e2a1d52-d93c-48e1-9da2-66121c8a0c57', 'sands-of-eon', 'Thundersoother', '5', 1000, 'https://genshin.jmp.blue/artifacts/thundersoother/sands-of-eon', 1000.0000, 'Electro RES increased by 40%', 'Increases DMG against enemies affected by Electro by 35%.');
INSERT INTO `artifact` (`artifactID`, `name`, `set_name`, `max_rarity`, `stock`, `image_url`, `price`, `piece_bonus_2`, `piece_bonus_4`) VALUES
('7f6f4587-4f5d-41c1-90df-cf48bfeb6812', 'flower-of-life', 'The Exile', '4', 1000, 'https://genshin.jmp.blue/artifacts/the-exile/flower-of-life', 1000.0000, 'Energy Recharge +20%', 'Using an Elemental Burst regenerates 2 Energy for other party members every 2s for 6s. This effect cannot stack.'),
('7f78f8b8-ef6c-4cad-859d-9c135a693a9a', 'plume-of-death', 'Brave Heart', '4', 1000, 'https://genshin.jmp.blue/artifacts/brave-heart/plume-of-death', 1000.0000, 'ATK +18%', 'Increases DMG by 30% against enemies with more than 50% HP.'),
('7fe20195-3920-4310-a2ca-465c7d7c11ab', 'sands-of-eon', 'Vourukasha\'s Glow', '5', 1000, 'https://genshin.jmp.blue/artifacts/vourukasha-s-glow/sands-of-eon', 1000.0000, 'HP +20%', 'Elemental Skill and Elemental Burst DMG will be increased by 10%. After the equipping character takes DMG, the aforementioned DMG bonus is increased by 80% for 5s. This effect increase can have 5 stacks. The duration of each stack is counted independently. These effects can be triggered even when the equipping character is not on the field.'),
('803e458e-572f-48b3-b540-a27b8b5094b7', 'plume-of-death', 'Martial Artist', '4', 1000, 'https://genshin.jmp.blue/artifacts/martial-artist/plume-of-death', 1000.0000, 'Increases Normal Attack and Charged Attack DMG by 15%.', 'After using Elemental Skill, increases Normal Attack and Charged Attack DMG by 25% for 8s.'),
('8146a7c1-c8ad-4fee-b526-cd17ea568a45', 'circlet-of-logos', 'Scholar', '4', 1000, 'https://genshin.jmp.blue/artifacts/scholar/circlet-of-logos', 1000.0000, 'Energy Recharge +20%.', 'Gaining Energy gives 3 Energy to all party members who have a bow or a catalyst equipped. Can only occurs once every 3s.'),
('82490da9-e2a4-4329-ad6d-1efeb16a71a8', 'circlet-of-logos', 'Tiny Miracle', '4', 1000, 'https://genshin.jmp.blue/artifacts/tiny-miracle/circlet-of-logos', 1000.0000, 'All Elemental RES increased by 20%', 'Incoming elemental DMG increases corresponding Elemental RES by 30% for 10s. Can only occur once every 10s.'),
('8315386c-21ec-494f-8604-a897c2ef6a11', 'flower-of-life', 'Martial Artist', '4', 1000, 'https://genshin.jmp.blue/artifacts/martial-artist/flower-of-life', 1000.0000, 'Increases Normal Attack and Charged Attack DMG by 15%.', 'After using Elemental Skill, increases Normal Attack and Charged Attack DMG by 25% for 8s.'),
('83f9e852-4765-47b1-bc99-55798b190dd8', 'goblet-of-eonothem', 'Nighttime Whispers in the Echoing Woods', '5', 1000, 'https://genshin.jmp.blue/artifacts/nighttime-whispers-in-the-echoing-woods/goblet-of-eonothem', 1000.0000, 'ATK +18%', 'After using an Elemental Skill, gain a 20% Geo DMG Bonus for 10s. While under a shield granted by the Crystallize reaction, the above effect will be increased by 150%, and this additional increase disappears 1s after that shield is lost.'),
('8575f943-046f-461e-b85b-029af2ccd94f', 'goblet-of-eonothem', 'Thundersoother', '5', 1000, 'https://genshin.jmp.blue/artifacts/thundersoother/goblet-of-eonothem', 1000.0000, 'Electro RES increased by 40%', 'Increases DMG against enemies affected by Electro by 35%.'),
('861d9aa2-56ab-4471-aaab-40c470b97a35', 'goblet-of-eonothem', 'Pale Flame', '5', 1000, 'https://genshin.jmp.blue/artifacts/pale-flame/goblet-of-eonothem', 1000.0000, 'Physical DMG +25%', 'When an Elemental Skill hits an opponent, ATK is increased by 9% for 7s. This effect stacks up to 2 times and can be triggered once every 0.3s. Once 2 stacks are reached the 2 set effect is increased by 100%.'),
('863ca706-3640-4ebd-ad4b-2b2778c350c8', 'circlet-of-logos', 'Resolution of Sojourner', '4', 1000, 'https://genshin.jmp.blue/artifacts/resolution-of-sojourner/circlet-of-logos', 1000.0000, 'ATK +18%', 'Increases Charged Attack CRIT Rate by 30%.'),
('866a761a-7c9d-4297-aa00-9f1ca81379ab', 'sands-of-eon', 'Adventurer', '3', 1000, 'https://genshin.jmp.blue/artifacts/adventurer/sands-of-eon', 1000.0000, 'Max HP increased by 1,000.', 'Opening chest regenerates 30% Max HP over 5s.'),
('87a622c1-4258-4251-91d4-0dddfce7e9e1', 'plume-of-death', 'Thundersoother', '5', 1000, 'https://genshin.jmp.blue/artifacts/thundersoother/plume-of-death', 1000.0000, 'Electro RES increased by 40%', 'Increases DMG against enemies affected by Electro by 35%.'),
('88c97877-dd8a-4342-98fd-2f55f4e28ad6', 'goblet-of-eonothem', 'Flower of Paradise Lost', '5', 1000, 'https://genshin.jmp.blue/artifacts/flower-of-paradise-lost/goblet-of-eonothem', 1000.0000, 'Increases Elemental Mastery by 80', 'The equipping character\'s Bloom, Hyperbloom, and Burgeon reaction DMG are increased by 40%. Additionally, after the equipping character triggers Bloom, Hyperbloom, or Burgeon, they will gain another 25% bonus to the effect mentioned prior. Each stack of this lasts 10s. Max 4 stacks simultaneously. This effect can only be triggered once per second. The character who equips this can still trigger its effects when not on the field.'),
('897423d5-330f-475a-9b64-9d87b4ba1bfb', 'circlet-of-logos', 'Retracing Bolide', '5', 1000, 'https://genshin.jmp.blue/artifacts/retracing-bolide/circlet-of-logos', 1000.0000, 'Increases Shield Strength by 35%.', 'While protected by a shield, gain an additional 40% Normal and Charged Attack DMG.'),
('897a35dd-5bd8-48a1-908a-4536d1f9ca30', 'flower-of-life', 'Echoes of an Offering', '5', 1000, 'https://genshin.jmp.blue/artifacts/echoes-of-an-offering/flower-of-life', 1000.0000, 'ATK +18%', 'When Normal Attacks hit opponents, there is a 36% chance that it will trigger Valley Rite, which will increase Normal Attack DMG by 70% of ATK. \nThis effect will be dispelled 0.05s after a Normal Attack deals DMG. \nIf a Normal Attack fails to trigger Valley Rite, the odds of it triggering the next time will increase by 20%. \nThis trigger can occur once every 0.2s.'),
('8bcf7a52-6799-4d95-81ad-376133fad0b4', 'sands-of-eon', 'Unfinished Reverie', '5', 1000, 'https://genshin.jmp.blue/artifacts/unfinished-reverie/sands-of-eon', 1000.0000, 'ATK +18%', 'After leaving combat for 3s, DMG dealt increased by 50%. In combat, if no Burning opponents are nearby for more than 6s, this DMG Bonus will decrease by 10% per second until it reaches 0%. When a Burning opponent exists, it will increase by 10% instead until it reaches 50%. This effect still triggers if the equipping character is off-field.'),
('8bfb5c59-3b66-4cf3-8f15-109e31d4950d', 'goblet-of-eonothem', 'Deepwood Memories', '5', 1000, 'https://genshin.jmp.blue/artifacts/deepwood-memories/goblet-of-eonothem', 1000.0000, 'Dendro DMG Bonus +15%', 'After Elemental Skills or Bursts hit opponents, the targets\' Dendro RES will be decreased by 30% for 8s. This effect can be triggered even if the equipping character is not on the field.'),
('8cb8ce10-7164-4ac9-b96e-36b7beb9a225', 'goblet-of-eonothem', 'Fragment of Harmonic Whimsy', '5', 1000, 'https://genshin.jmp.blue/artifacts/fragment-of-harmonic-whimsy/goblet-of-eonothem', 1000.0000, 'ATK +18%', 'When the value of a Bond of Life increases or decreases, this character deals 18% increased DMG for 6s. Max 3 stacks.'),
('8eab7f7b-6161-42f6-a6dc-f97dde0724d8', 'sands-of-eon', 'Ocean-Hued Clam', '5', 1000, 'https://genshin.jmp.blue/artifacts/ocean-hued-clam/sands-of-eon', 1000.0000, 'Healing Bonus +15%', 'When the character equipping this artifact set heals a character in the party, a Sea-Dyed Foam will appear for 3 seconds, accumulating the amount of HP recovered from healing (including overflow healing). At the end of the duration, the Sea-Dyed Foam will explode, dealing DMG to nearby opponents based on 90% of the accumulated healing. (This DMG is calculated similarly to Reactions such as Electro-Charged, and Superconduct, but it is not affected by Elemental Mastery, Character Levels, or Reaction DMG Bonuses). Only one Sea-Dyed Foam can be produced every 3.5 seconds. Each Sea-Dyed Foam can accumulate up to 30,000 HP (including overflow healing). There can be no more than one Sea-Dyed Foam active at any given time. This effect can still be triggered even when the character who is using this artifact set is not on the field.'),
('8f10cc2b-100c-4d6b-9c7d-711446cde57a', 'goblet-of-eonothem', 'Brave Heart', '4', 1000, 'https://genshin.jmp.blue/artifacts/brave-heart/goblet-of-eonothem', 1000.0000, 'ATK +18%', 'Increases DMG by 30% against enemies with more than 50% HP.'),
('909d1fce-2937-468b-b704-cb179c918142', 'sands-of-eon', 'Golden Troupe', '5', 1000, 'https://genshin.jmp.blue/artifacts/golden-troupe/sands-of-eon', 1000.0000, 'Increases Elemental Skill DMG by 20%.', 'Increases Elemental Skill DMG by 25%. Additionally, when not on the field, Elemental Skill DMG will be further increased by 25%. This effect will be cleared 2s after taking the field.'),
('9194579f-3f46-453a-877f-aa5b1af83dc8', 'goblet-of-eonothem', 'Traveling Doctor', '3', 1000, 'https://genshin.jmp.blue/artifacts/traveling-doctor/goblet-of-eonothem', 1000.0000, 'Increases incoming healing by 20%.', 'Using Elemental Burst restores 20% HP.'),
('94c6f941-1856-4a06-aae5-2a91b1aef548', 'flower-of-life', 'Emblem Of Severed Fate', '5', 1000, 'https://genshin.jmp.blue/artifacts/emblem-of-severed-fate/flower-of-life', 1000.0000, 'Energy Recharge + 20%', 'Increases Elemental Burst DMG by 25% of Energy Recharge. A maximum of 75% bonus DMG can be obtained in this way.'),
('95ee6ba9-1ea5-481b-80b3-295d36d2c99f', 'flower-of-life', 'Deepwood Memories', '5', 1000, 'https://genshin.jmp.blue/artifacts/deepwood-memories/flower-of-life', 1000.0000, 'Dendro DMG Bonus +15%', 'After Elemental Skills or Bursts hit opponents, the targets\' Dendro RES will be decreased by 30% for 8s. This effect can be triggered even if the equipping character is not on the field.'),
('96f39b3e-e7c2-461a-82d9-07999c344d2d', 'flower-of-life', 'Viridescent Venerer', '5', 1000, 'https://genshin.jmp.blue/artifacts/viridescent-venerer/flower-of-life', 1000.0000, 'Gain a 15% Anemo DMG Bonus.', 'Increases Swirl DMG by 60%. Decreases opponent\'s Elemental RES to the element infused in the Swirl by 40% for 10s.'),
('9755edf7-356c-4ca9-a8a4-124baff8d6ae', 'plume-of-death', 'Marechaussee Hunter', '5', 1000, 'https://genshin.jmp.blue/artifacts/marechaussee-hunter/plume-of-death', 1000.0000, 'Normal and Charged Attack DMG +15%.', 'When current HP increases or decreases, CRIT Rate will be increased by 12% for 5s. Max 3 stacks.'),
('98828e88-f096-454a-b607-408bebbb59f3', 'sands-of-eon', 'Crimson Witch of Flames', '5', 1000, 'https://genshin.jmp.blue/artifacts/crimson-witch-of-flames/sands-of-eon', 1000.0000, 'Gain a 15% Pyro DMG Bonus.', 'Increases Overloaded and Burning DMG by 40%. Increases Vaporize and Melt DMG by 15%. Using an Elemental Skill increases 2-Piece Set effects by 50% for 10s. Max 3 stacks.'),
('9889992c-3b25-4325-be4e-c2c207e0a267', 'sands-of-eon', 'The Exile', '4', 1000, 'https://genshin.jmp.blue/artifacts/the-exile/sands-of-eon', 1000.0000, 'Energy Recharge +20%', 'Using an Elemental Burst regenerates 2 Energy for other party members every 2s for 6s. This effect cannot stack.'),
