('a183ac8b-6133-4bc2-9f64-a6db83c0d1e1', 'flower-of-life', 'Tenacity of the Millelith', '5', 1000, 'https://genshin.jmp.blue/artifacts/tenacity-of-the-millelith/flower-of-life', 1000.0000, 'HP +20%', 'When an Elemental Skill hits an opponent, the ATK of all nearby party members is increased by 20% and their Shield Strength is increased by 30% for 3s. This effect can be triggered once every 0.5s. This effect can still be triggered even when the character who is using this artifact set is not on the field.'),
('a5fdcd7b-b572-442f-b9f2-ceb846334887', 'circlet-of-logos', 'Noblesse Oblige', '5', 1000, 'https://genshin.jmp.blue/artifacts/noblesse-oblige/circlet-of-logos', 1000.0000, 'Elemental Burst DMG +20%', 'Using an Elemental Burst increase all party members\' ATK by 20% for 12s. This effect cannot stack.'),
('a6c2dd1d-e75e-4311-abc0-7df866ec28c8', 'circlet-of-logos', 'Thundersoother', '5', 1000, 'https://genshin.jmp.blue/artifacts/thundersoother/circlet-of-logos', 1000.0000, 'Electro RES increased by 40%', 'Increases DMG against enemies affected by Electro by 35%.'),
