('a768cfff-ee91-451d-b67a-b16aaf52559c', 'flower-of-life', 'Blizzard Strayer', '5', 1000, 'https://genshin.jmp.blue/artifacts/blizzard-strayer/flower-of-life', 1000.0000, 'Cryo DMG Bonus +15%', 'When a character attacks an enemy affected by Cryo, their CRIT Rate is increased by 20%. If the enemy is Frozen, CRIT Rate is increased by an additional 20%.'),
('a981f2df-89a2-4cfd-9329-749971ba2909', 'goblet-of-eonothem', 'Instructor', '4', 1000, 'https://genshin.jmp.blue/artifacts/instructor/goblet-of-eonothem', 1000.0000, 'Increases Elemental Mastery by 80.', 'After using Elemental Skill, increases all party members\' Elemental Mastery by 120 for 8s.'),
('aa48c338-0989-4a2e-bc82-523cf78f97c0', 'plume-of-death', 'Resolution of Sojourner', '4', 1000, 'https://genshin.jmp.blue/artifacts/resolution-of-sojourner/plume-of-death', 1000.0000, 'ATK +18%', 'Increases Charged Attack CRIT Rate by 30%.'),
('abd42a3d-1358-4909-8979-ee010f951223', 'goblet-of-eonothem', 'Husk of Opulent Dreams', '5', 1000, 'https://genshin.jmp.blue/artifacts/husk-of-opulent-dreams/goblet-of-eonothem', 1000.0000, 'DEF +30%', 'A character equipped with this Artifact set will obtain the Curiosity effect in the following conditions: When on the field, the character gains 1 stack after hitting an opponent with a Geo attack, triggering a maximum of once every 0.3s. When off the field, the character gains 1 stack every 3s. Curiosity can stack up to 4 times, each providing 6% DEF and a 6% Geo DMG Bonus. When 6 seconds pass without gaining a Curiosity stack, 1 stack is lost.'),
('ad130aeb-e07c-4d10-b193-c8c9449ee1c6', 'circlet-of-logos', 'Gambler', '4', 1000, 'https://genshin.jmp.blue/artifacts/gambler/circlet-of-logos', 1000.0000, 'Elemental Skill DMG increased by 20%', 'Defeating an enemy has 100% chance to remove Elemental Skill CD. Can only occur once every 15s.'),
('af54ba33-ecd4-4eec-a76a-15fe746bfce2', 'circlet-of-logos', 'Echoes of an Offering', '5', 1000, 'https://genshin.jmp.blue/artifacts/echoes-of-an-offering/circlet-of-logos', 1000.0000, 'ATK +18%', 'When Normal Attacks hit opponents, there is a 36% chance that it will trigger Valley Rite, which will increase Normal Attack DMG by 70% of ATK. \nThis effect will be dispelled 0.05s after a Normal Attack deals DMG. \nIf a Normal Attack fails to trigger Valley Rite, the odds of it triggering the next time will increase by 20%. \nThis trigger can occur once every 0.2s.'),
('afeb29e8-ea50-4c3c-b38f-372540c79206', 'circlet-of-logos', 'Crimson Witch of Flames', '5', 1000, 'https://genshin.jmp.blue/artifacts/crimson-witch-of-flames/circlet-of-logos', 1000.0000, 'Gain a 15% Pyro DMG Bonus.', 'Increases Overloaded and Burning DMG by 40%. Increases Vaporize and Melt DMG by 15%. Using an Elemental Skill increases 2-Piece Set effects by 50% for 10s. Max 3 stacks.'),
('b07ca172-2694-41b0-9e56-460affdda7e7', 'circlet-of-logos', 'Golden Troupe', '5', 1000, 'https://genshin.jmp.blue/artifacts/golden-troupe/circlet-of-logos', 1000.0000, 'Increases Elemental Skill DMG by 20%.', 'Increases Elemental Skill DMG by 25%. Additionally, when not on the field, Elemental Skill DMG will be further increased by 25%. This effect will be cleared 2s after taking the field.'),
('b17e7777-9588-44c6-904b-389fd5724e7d', 'goblet-of-eonothem', 'Unfinished Reverie', '5', 1000, 'https://genshin.jmp.blue/artifacts/unfinished-reverie/goblet-of-eonothem', 1000.0000, 'ATK +18%', 'After leaving combat for 3s, DMG dealt increased by 50%. In combat, if no Burning opponents are nearby for more than 6s, this DMG Bonus will decrease by 10% per second until it reaches 0%. When a Burning opponent exists, it will increase by 10% instead until it reaches 50%. This effect still triggers if the equipping character is off-field.'),
('b1d50953-08e9-4eff-b54c-47dc5fec945e', 'plume-of-death', 'Retracing Bolide', '5', 1000, 'https://genshin.jmp.blue/artifacts/retracing-bolide/plume-of-death', 1000.0000, 'Increases Shield Strength by 35%.', 'While protected by a shield, gain an additional 40% Normal and Charged Attack DMG.'),
('b21cf41c-3545-4080-8a87-a912307b59e5', 'flower-of-life', 'Vermillion Hereafter', '5', 1000, 'https://genshin.jmp.blue/artifacts/vermillion-hereafter/flower-of-life', 1000.0000, 'ATK +18%', 'After using an Elemental Burst. this character will gain the Nascent Light effect, increasing their ATK by 8% for 16s. When the character\'s HP decreases, their ATK will further increase by 10%. This increase can occur this way maximum of 4 times. This effect can be triggered once every 0.8s. Nascent Light will be dispelled when the character leaves the field. If an Elemental Burst is used again during the duration of Nascent Light, the original Nascent Light will be dispelled.'),
('b33dcf2d-8a87-4d0d-a803-f41354efc8c3', 'goblet-of-eonothem', 'Lucky Dog', '3', 1000, 'https://genshin.jmp.blue/artifacts/lucky-dog/goblet-of-eonothem', 1000.0000, 'DEF increased by 100.', 'Picking up Mora restores 300 HP.'),
('b44b19a0-4918-4f93-8571-0447124bdf75', 'flower-of-life', 'Resolution of Sojourner', '4', 1000, 'https://genshin.jmp.blue/artifacts/resolution-of-sojourner/flower-of-life', 1000.0000, 'ATK +18%', 'Increases Charged Attack CRIT Rate by 30%.'),
('b6176f67-2e72-4bad-bbbb-1fdbb9aedaf8', 'plume-of-death', 'Unfinished Reverie', '5', 1000, 'https://genshin.jmp.blue/artifacts/unfinished-reverie/plume-of-death', 1000.0000, 'ATK +18%', 'After leaving combat for 3s, DMG dealt increased by 50%. In combat, if no Burning opponents are nearby for more than 6s, this DMG Bonus will decrease by 10% per second until it reaches 0%. When a Burning opponent exists, it will increase by 10% instead until it reaches 50%. This effect still triggers if the equipping character is off-field.'),
('b77e164c-90ac-4136-9247-3a495be0b36d', 'plume-of-death', 'Tenacity of the Millelith', '5', 1000, 'https://genshin.jmp.blue/artifacts/tenacity-of-the-millelith/plume-of-death', 1000.0000, 'HP +20%', 'When an Elemental Skill hits an opponent, the ATK of all nearby party members is increased by 20% and their Shield Strength is increased by 30% for 3s. This effect can be triggered once every 0.5s. This effect can still be triggered even when the character who is using this artifact set is not on the field.'),
('b8ca4940-d997-4863-8942-9db01d688de9', 'sands-of-eon', 'Fragment of Harmonic Whimsy', '5', 1000, 'https://genshin.jmp.blue/artifacts/fragment-of-harmonic-whimsy/sands-of-eon', 1000.0000, 'ATK +18%', 'When the value of a Bond of Life increases or decreases, this character deals 18% increased DMG for 6s. Max 3 stacks.'),
('b9c5e179-9595-4d31-8f93-7549b3baa022', 'circlet-of-logos', 'Husk of Opulent Dreams', '5', 1000, 'https://genshin.jmp.blue/artifacts/husk-of-opulent-dreams/circlet-of-logos', 1000.0000, 'DEF +30%', 'A character equipped with this Artifact set will obtain the Curiosity effect in the following conditions: When on the field, the character gains 1 stack after hitting an opponent with a Geo attack, triggering a maximum of once every 0.3s. When off the field, the character gains 1 stack every 3s. Curiosity can stack up to 4 times, each providing 6% DEF and a 6% Geo DMG Bonus. When 6 seconds pass without gaining a Curiosity stack, 1 stack is lost.'),
('bb4c5bea-494d-46cd-81f5-c67faddd4afc', 'flower-of-life', 'Desert Pavilion Chronicle', '5', 1000, 'https://genshin.jmp.blue/artifacts/desert-pavilion-chronicle/flower-of-life', 1000.0000, 'Anemo DMG Bonus +15%', 'When Charged Attacks hit opponents, the equipping character\'s Normal Attack SPD will increase by 10% while Normal, Charged, and Plunging Attack DMG will increase by 40% for 15s.'),
('bbcd1ffd-67ee-4813-ac2c-fff4a9a7ad3a', 'flower-of-life', 'Husk of Opulent Dreams', '5', 1000, 'https://genshin.jmp.blue/artifacts/husk-of-opulent-dreams/flower-of-life', 1000.0000, 'DEF +30%', 'A character equipped with this Artifact set will obtain the Curiosity effect in the following conditions: When on the field, the character gains 1 stack after hitting an opponent with a Geo attack, triggering a maximum of once every 0.3s. When off the field, the character gains 1 stack every 3s. Curiosity can stack up to 4 times, each providing 6% DEF and a 6% Geo DMG Bonus. When 6 seconds pass without gaining a Curiosity stack, 1 stack is lost.'),
('bd833ba8-9289-4517-897b-aafbd213e604', 'goblet-of-eonothem', 'Desert Pavilion Chronicle', '5', 1000, 'https://genshin.jmp.blue/artifacts/desert-pavilion-chronicle/goblet-of-eonothem', 1000.0000, 'Anemo DMG Bonus +15%', 'When Charged Attacks hit opponents, the equipping character\'s Normal Attack SPD will increase by 10% while Normal, Charged, and Plunging Attack DMG will increase by 40% for 15s.'),
('bdce0218-b3ba-455f-a034-eb054fa385ae', 'sands-of-eon', 'Pale Flame', '5', 1000, 'https://genshin.jmp.blue/artifacts/pale-flame/sands-of-eon', 1000.0000, 'Physical DMG +25%', 'When an Elemental Skill hits an opponent, ATK is increased by 9% for 7s. This effect stacks up to 2 times and can be triggered once every 0.3s. Once 2 stacks are reached the 2 set effect is increased by 100%.'),
('be7ceb10-a602-4692-857b-91fb955ee6d8', 'sands-of-eon', 'Archaic Petra', '5', 1000, 'https://genshin.jmp.blue/artifacts/archaic-petra/sands-of-eon', 1000.0000, 'Gain a 15% Geo DMG Bonus.', 'Upon obtaining an Elemental Shard created through a Crystallize Reaction, all party members gain a 35% DMG Bonus for that particular element for 10s. Only one form of Elemental DMG Bonus can be gained in this manner at any one time.'),
('becfe246-6f9f-42a9-8dc0-d444c5a04ee0', 'circlet-of-logos', 'Traveling Doctor', '3', 1000, 'https://genshin.jmp.blue/artifacts/traveling-doctor/circlet-of-logos', 1000.0000, 'Increases incoming healing by 20%.', 'Using Elemental Burst restores 20% HP.'),
('beeceb98-bc33-4f7f-a6df-aeec6b7b8507', 'circlet-of-logos', 'Pale Flame', '5', 1000, 'https://genshin.jmp.blue/artifacts/pale-flame/circlet-of-logos', 1000.0000, 'Physical DMG +25%', 'When an Elemental Skill hits an opponent, ATK is increased by 9% for 7s. This effect stacks up to 2 times and can be triggered once every 0.3s. Once 2 stacks are reached the 2 set effect is increased by 100%.'),
