('bff210b1-77cf-4bde-91c4-1236eb89f6e9', 'flower-of-life', 'Archaic Petra', '5', 1000, 'https://genshin.jmp.blue/artifacts/archaic-petra/flower-of-life', 1000.0000, 'Gain a 15% Geo DMG Bonus.', 'Upon obtaining an Elemental Shard created through a Crystallize Reaction, all party members gain a 35% DMG Bonus for that particular element for 10s. Only one form of Elemental DMG Bonus can be gained in this manner at any one time.'),
('c02d50dd-cbcb-40a1-9d92-394e6d607c8e', 'plume-of-death', 'Wanderer\'s Troupe', '5', 1000, 'https://genshin.jmp.blue/artifacts/wanderer-s-troupe/plume-of-death', 1000.0000, 'Elemental Mastery +80', 'Increases Charged Attack DMG by 35% if the character uses a Catalyst or Bow.'),
('c09f860b-c1f0-4d05-a6e1-8efd8a678c8e', 'circlet-of-logos', 'Adventurer', '3', 1000, 'https://genshin.jmp.blue/artifacts/adventurer/circlet-of-logos', 1000.0000, 'Max HP increased by 1,000.', 'Opening chest regenerates 30% Max HP over 5s.'),
('c2220ab0-4324-40d5-90e1-70cbccd26add', 'goblet-of-eonothem', 'Berserker', '4', 1000, 'https://genshin.jmp.blue/artifacts/berserker/goblet-of-eonothem', 1000.0000, 'CRIT Rate +12%', 'When HP is below 70%, CRIT Rate increases by an additional 24%.'),
('c350109d-bc6b-4b19-895a-c06f86f45702', 'flower-of-life', 'Song of Days Past', '5', 1000, 'https://genshin.jmp.blue/artifacts/song-of-days-past/flower-of-life', 1000.0000, 'Healing Bonus +15%', 'When the equipping character heals a party member, the Yearning effect will be created for 6s, which records the total amount of healing provided (including overflow healing). When the duration expires, the Yearning effect will be transformed into the \"Waves of Days Past\" effect: When your active party member hits an opponent with a Normal Attack, Charged Attack, Plunging Attack, Elemental Skill, or Elemental Burst, the DMG dealt will be increased by 8% of the total healing amount recorded by the Yearning effect. The \"Waves of Days Past\" effect is removed after it has taken effect 5 times or after 10s. A single instance of the Yearning effect can record up to 15,000 healing, and only a single instance can exist at once, but it can record the healing from multiple equipping characters. Equipping characters on standby can still trigger this effect.'),
('c358cfc0-1fec-4324-8945-aa1c0d8f0064', 'plume-of-death', 'Archaic Petra', '5', 1000, 'https://genshin.jmp.blue/artifacts/archaic-petra/plume-of-death', 1000.0000, 'Gain a 15% Geo DMG Bonus.', 'Upon obtaining an Elemental Shard created through a Crystallize Reaction, all party members gain a 35% DMG Bonus for that particular element for 10s. Only one form of Elemental DMG Bonus can be gained in this manner at any one time.'),
('c725fdd3-86a8-41ae-a7fe-96513807a051', 'sands-of-eon', 'Blizzard Strayer', '5', 1000, 'https://genshin.jmp.blue/artifacts/blizzard-strayer/sands-of-eon', 1000.0000, 'Cryo DMG Bonus +15%', 'When a character attacks an enemy affected by Cryo, their CRIT Rate is increased by 20%. If the enemy is Frozen, CRIT Rate is increased by an additional 20%.'),
('c85c2b55-b354-4c66-83a2-b210408a8bb7', 'goblet-of-eonothem', 'Gambler', '4', 1000, 'https://genshin.jmp.blue/artifacts/gambler/goblet-of-eonothem', 1000.0000, 'Elemental Skill DMG increased by 20%', 'Defeating an enemy has 100% chance to remove Elemental Skill CD. Can only occur once every 15s.'),
('c9118a6a-8866-454e-85c0-d32e6cc0c870', 'goblet-of-eonothem', 'Lavawalker', '5', 1000, 'https://genshin.jmp.blue/artifacts/lavawalker/goblet-of-eonothem', 1000.0000, 'Pyro RES increased by 40%', 'Increases DMG against enemies that are Burning or affected by Pyro by 35%.'),
('ca6b6b07-aa00-45db-9207-e3e305844234', 'circlet-of-logos', 'Ocean-Hued Clam', '5', 1000, 'https://genshin.jmp.blue/artifacts/ocean-hued-clam/circlet-of-logos', 1000.0000, 'Healing Bonus +15%', 'When the character equipping this artifact set heals a character in the party, a Sea-Dyed Foam will appear for 3 seconds, accumulating the amount of HP recovered from healing (including overflow healing). At the end of the duration, the Sea-Dyed Foam will explode, dealing DMG to nearby opponents based on 90% of the accumulated healing. (This DMG is calculated similarly to Reactions such as Electro-Charged, and Superconduct, but it is not affected by Elemental Mastery, Character Levels, or Reaction DMG Bonuses). Only one Sea-Dyed Foam can be produced every 3.5 seconds. Each Sea-Dyed Foam can accumulate up to 30,000 HP (including overflow healing). There can be no more than one Sea-Dyed Foam active at any given time. This effect can still be triggered even when the character who is using this artifact set is not on the field.'),
('cc998d89-d0e7-4ca0-9445-613032ffe103', 'plume-of-death', 'Defender\'s Will', '4', 1000, 'https://genshin.jmp.blue/artifacts/defender-s-will/plume-of-death', 1000.0000, 'Base DEF +30%', 'Increases Elemental RES by 30% for each element present in the party.'),
