('f96682ac-ff09-45ad-b5fc-ec8182bd4211', 'Fillet Blade', 'Sword', '3', '39', 'ATK', 'Gash', 'On hit, has 50% chance to deal 240/280/320/360/400% ATK DMG to a single enemy. Can only occur once every 15/14/13/12/11s.', 'https://genshin.jmp.blue/weapons/fillet-blade/icon.png', 1000.0000, 1000, '2026-06-05 11:50:20', '2026-06-05 11:50:20'),
('fb554fce-3f25-4589-88b3-b40c93fdfe73', 'The Black Sword', 'Sword', '4', '42', 'CRIT Rate', 'Justice', 'Increases DMG dealt by Normal and Charged Attacks by 20%.\nAdditionally, regenerates 60% of ATK as HP when Normal and Charged Attacks score a CRIT Hit. This effect can occur once every 5s.', 'https://genshin.jmp.blue/weapons/the-black-sword/icon.png', 1000.0000, 1000, '2026-06-05 11:50:47', '2026-06-05 11:50:47'),
